 "content": "def transform(grid):
    """Decode adjacent 2x2 blocks: solid squares and 3-cell L tiles.

    The input uses 8 for every occupied tile cell and 0 for empty cells.
    A complete 2x2 block becomes color 1. Missing-corner L blocks use
    color 2 (missing top-left), 4 (missing top-right), or 3 (missing
    bottom-left); the remaining orientation is unsupported by demos.
    """
    h, w = len(grid), len(grid[0])
    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    tiles = []
    for r in range(h - 1):
        for c in range(w - 1):
            corners = {(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)}
            present = corners & occupied
            if len(present) == 4:
                tiles.append((present, 1))
            elif len(present) == 3:
                missing = next(iter(corners - present))
                # Colors are identified by the missing corner's orientation.
                color = {(r, c): 2, (r, c + 1): 4, (r + 1, c): 3}.get(missing)
                if color is not None:
                    tiles.append((present, color))

    # Select non-overlapping tiles that exactly cover the occupied cells.
    # ARC inputs here are small; backtracking also avoids accidentally
    # coloring arbitrary overlapping 2x2 windows in the fused silhouettes.
    by_cell = {cell: [] for cell in occupied}
    for cells, color in tiles:
        for cell in cells:
            by_cell[cell].append((cells, color))

    def cover(remaining):
        if not remaining:
            return []
        cell = min(remaining)
        for cells, color in by_cell[cell]:
            if cells <= remaining:
                rest = cover(remaining - cells)
                if rest is not None:
                    return [(cells, color)] + rest
        return None

    selected = cover(occupied)
    out = [[0] * w for _ in range(h)]
    if selected is not None:
        for cells, color in selected:
            for r, c in cells:
                out[r][c] = color
    return out
